/// E014's deny-list must cover what the Arduino core really declares. The list is generated by
/// tool/extract_arduino_names.sh; this test re-runs that extraction against the installed core and fails if any
/// name it finds would be accepted as a user name (e.g. after an arduino:avr core upgrade).
@Tags(['arduino'])
library;

import 'dart:io';

import 'package:test/test.dart';
import 'package:unodar_compiler/src/api/api_registry.dart';
import 'package:unodar_compiler/src/emitter/emitter.dart';
import 'package:unodar_compiler/src/validator/rules.dart';

import 'arduino_toolchain.dart';
import 'test_paths.dart';

bool reserved(String name) =>
    reservedNameProblem(name, api: ApiRegistry.core().reservedNames, arduino: const UnoTarget().reservedNames) != null;

void main() {
  final gate = arduinoGate();

  test('the names the maintainer listed are reserved', () {
    for (final name in [
      'min',
      'max',
      'abs',
      'round',
      'sq',
      'map',
      'constrain',
      'bit',
      'word',
      'byte',
      'u8',
      'Serial'
    ]) {
      expect(reserved(name), isTrue, reason: name);
    }
    for (final name in ['ledPin', 'count', 'pulse', 'squared', 'level']) {
      expect(reserved(name), isFalse, reason: name);
    }
  });

  test('every global name of the installed Arduino AVR core is reserved', () async {
    gate.check();
    final run = await Process.run(fromPackage('..', '..', 'tool', 'extract_arduino_names.sh'), const []);
    expect(run.exitCode, 0, reason: '${run.stderr}');
    final names = (run.stdout as String).split('\n').where((n) => n.isNotEmpty).toList();
    expect(names.length, greaterThan(500), reason: 'the extraction found suspiciously few names');
    final missing = names.where((n) => !reserved(n)).toList();
    expect(missing, isEmpty, reason: 'regenerate lib/src/emitter/arduino_avr_names.dart with the tool');
  }, skip: gate.skip, timeout: const Timeout(Duration(minutes: 2)));
}
